function getSheet(tab, sourceId = sheetId) {
  const callback = `ycacPicker_${tab}_${Date.now()}`;
  const query = new URLSearchParams({ tqx: `out:json;responseHandler:${callback}`, sheet: tab });
  return new Promise((resolve, reject) => {
    const script = document.createElement("script");
    const cleanup = () => { script.remove(); delete window[callback]; };
    window[callback] = (response) => { cleanup(); if (response.status !== "ok") { reject(new Error(`Could not load ${tab}`)); return; } let headers = response.table.cols.map((column) => column.label), rows = response.table.rows; if (headers.every((header) => !header) && rows.length) { headers = rows[0].c.map((cell) => cell?.v ?? ""); rows = rows.slice(1); } resolve(rows.map((row) => Object.fromEntries(headers.map((header, index) => [header, row.c[index]?.v ?? ""])))); };
    script.onerror = () => { cleanup(); reject(new Error(`Could not load ${tab}`)); };
    script.src = `https://docs.google.com/spreadsheets/d/${sourceId}/gviz/tq?${query}`;
    document.head.append(script);
  });
}

function selectedEvent() { return data.Matches.find((match) => match.match_id === document.querySelector("#event").value); }
function isPast(match) { return match.ycac_goals !== "" && match.opponent_goals !== ""; }
function availablePlayerIds() { const match = selectedEvent(); if (!match) return new Set(); if (data.Appearances.some((appearance) => appearance.match_id === match.match_id)) return new Set(data.Appearances.filter((appearance) => appearance.match_id === match.match_id).map((appearance) => appearance.player_id)); return new Set(data.EventSignups.filter((signup) => signup.match_id === match.match_id && !["declined", "out", "unavailable"].includes(String(signup.status).toLowerCase())).map((signup) => signup.player_id)); }
function eventPlayers() { const ids = availablePlayerIds(); return players.filter((player) => ids.has(player.player_id)); }
function setStatus(text) { document.querySelector("#picker-status").textContent = text; }
function refreshBench() { if (!benchEnabled) { substitutes = []; return; } const startingIds = new Set(slots.map((slot) => slot.playerId).filter(Boolean)); substitutes = eventPlayers().filter((player) => !startingIds.has(player.player_id)).sort((a, b) => historicalScore(b, positionGroup(b.primary_position)) - historicalScore(a, positionGroup(a.primary_position))).slice(0, 9).map((player) => player.player_id); }

function resetFormation() { slots = formations[document.querySelector("#formation").value].flat().map((role, index) => ({ id: index, role, playerId: null })); substitutes = []; active = null; benchEnabled = false; document.querySelector("#formation-name").textContent = document.querySelector("#formation").selectedOptions[0].text; render(); }
function assignToStarter(playerId, preferredRole) { const target = slots.find((slot) => !slot.playerId && slot.role === preferredRole) || slots.find((slot) => !slot.playerId); if (target) target.playerId = playerId; return Boolean(target); }
function historicalScore(player, role) { const completedIds = new Set(data.Matches.filter(isPast).map((match) => match.match_id)); const appearances = data.Appearances.filter((appearance) => appearance.player_id === player.player_id && completedIds.has(appearance.match_id)); const goals = data.Goals.filter((goal) => goal.scorer_id === player.player_id && completedIds.has(goal.match_id)).length; const appearanceScore = appearances.reduce((score, appearance) => { const sameRole = positionGroup(appearance.position || player.primary_position) === role; if (appearance.role === "starter") return score + (sameRole ? 8 : 3); return score + (sameRole ? 3 : 1); }, 0); const attackingBonus = role === "AT" ? goals * 10 : role === "MF" ? goals * 4 : goals; return appearanceScore + attackingBonus; }
function suggestSquad() { resetFormation(); const available = eventPlayers(); for (const slot of slots) { const candidate = available.filter((player) => !slots.some((item) => item.playerId === player.player_id) && positionGroup(player.primary_position) === slot.role).sort((a, b) => historicalScore(b, slot.role) - historicalScore(a, slot.role))[0]; if (candidate) slot.playerId = candidate.player_id; }
  benchEnabled = true; setStatus(t("pickerStatusSuggested")); render(); }
function loadPastLineup() { resetFormation(); const match = selectedEvent(); const appearances = data.Appearances.filter((appearance) => appearance.match_id === match.match_id); appearances.filter((appearance) => appearance.role === "starter").forEach((appearance) => assignToStarter(appearance.player_id, positionGroup(appearance.position || players.find((player) => player.player_id === appearance.player_id)?.primary_position))); benchEnabled = true; setStatus(t("pickerStatusPast")); render(); }
function loadSavedLineup() { const match = selectedEvent(); const candidates = data.SavedSquads.filter((squad) => squad.match_id === match.match_id && squad.active !== false && String(squad.active).toLowerCase() !== "false"); const latestId = candidates.map((squad) => squad.saved_squad_id).filter(Boolean).pop(); const saved = candidates.filter((squad) => squad.saved_squad_id === latestId).sort((a, b) => Number(a.slot_order) - Number(b.slot_order)); if (saved[0]?.formation && formations[saved[0].formation]) document.querySelector("#formation").value = saved[0].formation; resetFormation(); saved.filter((squad) => squad.selection_type === "starter").forEach((squad) => assignToStarter(squad.player_id, positionGroup(players.find((player) => player.player_id === squad.player_id)?.primary_position))); benchEnabled = true; setStatus(t("pickerStatusSavedLoaded")); render(); }
function renderEventDetails() { const match = selectedEvent(); if (!match) return; document.querySelector("#event-details").innerHTML = `<span><strong>${t("pickerDate")}</strong>${match.date}</span><span><strong>${t("pickerOpponent")}</strong>${match.opponent}</span><span><strong>${t("pickerCompetition")}</strong>${match.competition}</span><span><strong>${t("pickerVenue")}</strong>${match.venue || "TBC"}</span><span><strong>${t("pickerKickoff")}</strong>${match.kickoff || "TBC"}</span>`; }
function changeEvent() { const match = selectedEvent(); if (!match) return; const hasActual = data.Appearances.some((appearance) => appearance.match_id === match.match_id); document.querySelector("#save-squad").disabled = hasActual; renderEventDetails(); if (hasActual) loadPastLineup(); else if (data.SavedSquads.some((squad) => squad.match_id === match.match_id && squad.active !== false && String(squad.active).toLowerCase() !== "false")) loadSavedLineup(); else { resetFormation(); setStatus(eventPlayers().length ? t("pickerStatusConfirmed") : t("pickerStatusNoSignups")); } }

function renderPitch() { const rows = [], formation = formations[document.querySelector("#formation").value]; let cursor = 0; for (const row of formation) { const rowSlots = slots.slice(cursor, cursor + row.length); cursor += row.length; rows.push(`<div class="pitch-row">${rowSlots.map((slot) => { const player = players.find((item) => item.player_id === slot.playerId); return `<button class="slot ${player ? "assigned" : ""} ${active?.area === "start" && active.index === slot.id ? "active" : ""}" type="button" data-slot="${slot.id}">${player ? `<span class="slot-number">${player.shirt_number || ""}</span><span class="slot-name">${player.display_name}</span>` : `<span class="slot-role">${slot.role}</span>`}</button>`; }).join("")}</div>`); } document.querySelector("#pitch").innerHTML = `<img class="pitch-crest" src="https://ycac.jp/wp-content/uploads/2025/10/YCAC-Logo-Icon.png" alt="" />${rows.join("")}`; document.querySelectorAll(".slot").forEach((button) => button.addEventListener("click", () => { active = { area: "start", index: Number(button.dataset.slot) }; setStatus(t("pickerStatusPickSlot", { role: slots[active.index].role })); render(); })); }
function renderBench() { document.querySelector("#bench").innerHTML = Array.from({ length: 9 }, (_, index) => { const player = players.find((item) => item.player_id === substitutes[index]); return `<div class="bench-slot ${player ? "assigned" : ""}"><span class="bench-index">${index + 1}</span><span class="bench-name">${player ? player.display_name : ui.open}</span></div>`; }).join(""); document.querySelector("#bench-count").textContent = substitutes.length; }
