function renderRoster() { const starting = new Set(slots.map((slot) => slot.playerId).filter(Boolean)), bench = new Set(substitutes), visible = eventPlayers().filter((player) => player.display_name.toLocaleLowerCase().includes(search)), groups = ["GK", "DF", "MF", "AT", "Other"]; document.querySelector("#roster").innerHTML = groups.map((group) => { const members = visible.filter((player) => positionGroup(player.primary_position) === group); if (!members.length) return ""; return `<section class="roster-group"><h3>${group}</h3><div class="player-list">${members.map((player) => { const state = starting.has(player.player_id) ? "starter-picked" : bench.has(player.player_id) ? "bench-picked" : ""; const label = starting.has(player.player_id) ? "XI" : bench.has(player.player_id) ? "SUB" : player.primary_position || group; return `<button class="player-card ${state}" type="button" data-player="${player.player_id}"><span class="player-number">${player.shirt_number || "–"}</span><span class="player-name">${player.display_name}</span><span class="player-position">${label}</span></button>`; }).join("")}</div></section>`; }).join("") || `<p class="loading">${t("pickerStatusNoEligible")}</p>`; document.querySelectorAll(".player-card").forEach((button) => button.addEventListener("click", () => assignPlayer(button.dataset.player))); }
function assignPlayer(playerId) { slots.forEach((slot) => { if (slot.playerId === playerId) slot.playerId = null; }); substitutes = substitutes.map((id) => id === playerId ? null : id); const player = players.find((item) => item.player_id === playerId); if (active?.area === "start") slots[active.index].playerId = playerId; else if (active?.area === "bench") substitutes[active.index] = playerId; else if (!assignToStarter(playerId, positionGroup(player.primary_position))) { const index = substitutes.findIndex((id) => !id); if (index >= 0) substitutes[index] = playerId; else { setStatus(t("pickerStatusFull")); render(); return; } } active = null; setStatus(t("pickerStatusAdded", { name: player.display_name })); render(); }
