Promise.all([...mainTabs.map(async (tab) => [tab, await getSheet(tab)]), ...pickerTabs.map(async (tab) => [tab, await getSheet(tab, squadPickerSheetId)])]).then((entries) => { data = Object.fromEntries(entries); players = data.Players.filter((player) => player.active !== false).sort((a, b) => positionOrder[positionGroup(a.primary_position)] - positionOrder[positionGroup(b.primary_position)] || a.display_name.localeCompare(b.display_name)); populateEvents(); changeEvent(); }).catch(() => { document.querySelector("#roster").innerHTML = `<p class="loading">${t("pickerLoadFailed")}</p>`; });

